1118	    onSuccess: () => {},
1119	  });
1120	}
1121	
1122	// Runs compensation for one already-succeeded business action. The call gets
1123	// independent structured clones of the input and earlier outputs captured at
1124	// the original action's success moment, the stored return value, the node id
1125	// and a 1-based compensation attempt number. Nothing here can touch the run
1126	// context, a later attempt, another run, or the stored success output.
1127	async function runCompensation(entry, implementation, records) {
1128	  const { nodeId, binding, snapshot } = entry;
1129	  return runWithRetries({
1130	    retry: binding.compensation.retry,
1131	    prepareArgs: attempt => [
1132	      structuredClone(snapshot.input), structuredClone(snapshot.output),
1133	      structuredClone(snapshot.result), nodeId, attempt,
1134	    ],
1135	    invoke: implementation,
1136	    createRecord: attempt => ({
1137	      nodeId, operation: binding.compensation.name, attempt,
1138	      ok: false, error: null, nextDelayMs: 0, result: null,
1139	    }),
1140	    cloneFailureMessage: `compensation "${binding.compensation.name}" returned a value that cannot be structured-cloned`,
1141	    sharedMemoryFailureMessage: `compensation "${binding.compensation.name}" returned a value that contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this return value is not supported`,
