1147	// Undoes successful compensable business actions, most recent first, waiting
1148	// for each compensation to finish before starting the next. A compensation
1149	// that exhausts its retries is recorded as failed but earlier (still-pending)
1150	// actions are compensated regardless; neither the failed compensation nor the
1151	// original business operation is re-run. Compensating a node removes it from
1152	// the pending list exactly once — retried-then-succeeded actions and shared
1153	// join nodes were only recorded once to begin with.
1154	async function compensateRun(state, operations) {
1155	  const records = [];
1156	  let failed = false;
1157	  while (state.compensable.length > 0) {
1158	    const entry = state.compensable.pop();
1159	    const outcome = await runCompensation(entry, operations[entry.binding.compensation.name], records);
1160	    if (!outcome.ok) failed = true;
1161	  }
1162	  return { status: failed ? 'failed' : 'completed', attempts: records };
1163	}
1164	
1165	// Scheduling state shared by the synchronous and asynchronous execution
1166	// loops: activation, completion, dependency gating and the recorded end
1167	// result all behave identically; only business-action handling differs.
1168	function createRunState(nodes, workflow, input) {
1169	  const declarationOrder = [...nodes.values()];
1170	  const declarationIndex = new Map(declarationOrder.map((node, index) => [node.id, index]));
1171	  return {
1172	    trace: [],
1173	    actionAttempts: [],
1174	    context: { input: structuredClone(input), output: {} },
1175	    declarationOrder,
1176	    declarationIndex,
1177	    activated: new Set([workflow.entry]),
1178	    completed: new Set(),
1179	    endReached: false,
1180	    endResult: null,
1181	    // Successful business actions that declared a compensation, in the order
1182	    // they succeeded. Each entry keeps independent snapshots captured at the
1183	    // action's own success moment.
1184	    compensable: [],
1185	  };
1186	}
