1188	function pickReadyNode(state) {
1189	  return state.declarationOrder.find(node =>
1190	    state.activated.has(node.id) && !state.completed.has(node.id)
1191	    && nodeDependencies.get(node).every(dependency => state.completed.has(dependency)));
1192	}
1193	
1194	function blockedResult(state) {
1195	  const waiting = state.declarationOrder.filter(node =>
1196	    state.activated.has(node.id) && !state.completed.has(node.id));
1197	  if (waiting.length === 0) return null;
1198	  return waiting.map(node => ({
1199	    nodeId: node.id,
1200	    missingDependencies: nodeDependencies.get(node)
1201	      .filter(dependency => !state.completed.has(dependency))
1202	      .sort((a, b) => state.declarationIndex.get(a) - state.declarationIndex.get(b)),
1203	  }));
1204	}
1205	
1206	// One shared scheduling step for the synchronous and asynchronous entries.
1207	// pickReadyNode already encodes activation plus dependency gating; this adds
1208	// the rules the two entries used to duplicate:
1209	// - a ready node is recorded in the trace the moment it enters execution, so
1210	//   waiting and never-activated nodes never appear in trace or output;
1211	// - an end node records its result and completes, but never stops the other
1212	//   activated branches — the caller simply loops again;
1213	// - with no ready node left, activated-but-waiting nodes classify the run as
1214	//   "blocked", a visited end node as "completed", and anything else is a
1215	//   structural cycle (validation rejects those before execution).
1216	// The terminal kinds are classifications only: each entry keeps building its
1217	// own result shape (the asynchronous one adds attempt and compensation
1218	// fields) so the public return values are unchanged.
1219	function advanceSchedule(state) {
1220	  const ready = pickReadyNode(state);
1221	  if (!ready) {
1222	    const waiting = blockedResult(state);
1223	    if (waiting) return { kind: 'blocked', waiting };
1224	    if (state.endReached) return { kind: 'completed' };
1225	    throw new Error('workflow did not terminate; a cycle is present');
1226	  }
1227	  state.trace.push({ nodeId: ready.id, type: ready.type });
1228	  if (ready.type === 'end') {
1229	    // Reaching an end node records the result but never stops other
1230	    // activated branches; the run completes once nothing can still run.
1231	    // Snapshot the result at this end node's own execution moment: the
1232	    // recorded value is this run's independent copy, so later mutation of
1233	    // the definition's result (during a wait on another activated branch),
1234	    // of another run's result, or of the returned value cannot reach back
1235	    // here. Validation already guarantees cloneability, so this cannot
1236	    // throw mid-run. An unset or null result stays null; 0, false and ""
1237	    // pass through ?? untouched (only null/undefined default to null).
1238	    state.endReached = true;
1239	    state.endResult = structuredClone(ready.result ?? null);
1240	    state.completed.add(ready.id);
