1244	}
1245	
1246	// Applies a ready non-action node, mutating activation/completion state.
1247	// Returns an early-termination result (invalid_input / invalid_condition)
1248	// or null when execution should continue.
1249	function applyRegularNode(node, state) {
1250	  if (node.type === 'action') {
1251	    // Snapshot the legacy message at this action's own execution moment: the
1252	    // saved output is this run's independent deep copy, so editing nested
1253	    // fields, adding or deleting properties, or changing array members of the
1254	    // returned output never reaches the definition, another run, or an output
1255	    // this action recorded while another activated branch is still waiting.
1256	    // An unset, undefined or null message defaults to action:<node id>;
1257	    // "", 0 and false pass through untouched. Validation already guarantees
1258	    // that an explicit message is structured-cloneable, so this cannot throw
1259	    // mid-run.
1260	    const hasMessage = Object.hasOwn(node, 'message') && node.message !== undefined && node.message !== null;
1261	    const value = hasMessage ? structuredClone(node.message) : `action:${node.id}`;
1262	    setNodeOutput(state.context.output, node.id, value);
1263	  }
1264	  if (node.type === 'form') {
1265	    const compiled = formSchemas.get(node);
1266	    if (compiled) {
1267	      const formResult = processForm(node, state.context.input, compiled);
1268	      if (!formResult.ok) {
1269	        state.context.input = formResult.rollback;
1270	        return { status: 'invalid_input', context: state.context, trace: state.trace, errors: formResult.errors };
1271	      }
1272	    }
1273	  }
1274	  if (node.type === 'condition') {
1275	    const outcome = runCondition(compiledConditions.get(node), state.context.input, state.context.output, node.id);
1276	    if (!outcome.ok) {
1277	      return { status: 'invalid_condition', context: state.context, trace: state.trace, error: outcome.error };
1278	    }
1279	    state.activated.add(outcome.value ? node.then : node.else);
1280	  } else {
1281	    for (const target of successorTargets.get(node)) state.activated.add(target);
1282	  }
1283	  state.completed.add(node.id);
