1285	}
1286	
1287	// Verifies, before a single node can run, that every business operation and
1288	// every compensation operation in the definition has a function registered —
1289	// including actions on untaken branches and entry-unreachable nodes.
1290	function resolveImplementation(operations, name, nodeId, kind) {
1291	  if (!isUsableObject(operations)
1292	    || !Object.hasOwn(operations, name)
1293	    || typeof operations[name] !== 'function') {
