1296	  return operations[name];
1297	}
1298	
1299	function verifyOperations(nodes, operations) {
1300	  for (const node of nodes.values()) {
1301	    const binding = actionBindings.get(node);
1302	    if (binding && binding.name !== null) {
1303	      resolveImplementation(operations, binding.name, node.id, 'business');
1304	    }
1305	    if (binding && binding.compensation !== null) {
1306	      resolveImplementation(operations, binding.compensation.name, node.id, 'compensation');
1307	    }
1308	  }
1309	}
1310	
1311	// The optional fourth argument of executeWorkflowAsync carries an
1312	// AbortSignal as `{ signal }`. Omitting it — or passing undefined, or an
1313	// options object without a signal — keeps the previous behavior; anything
1314	// else is a caller error reported before a single node executes.
1315	function resolveRunSignal(options) {
1316	  if (options === undefined) return null;
1317	  if (!isUsableObject(options)) {
1318	    throw new TypeError('executeWorkflowAsync options must be an object with an optional "signal" AbortSignal');
1319	  }
1320	  if (!Object.hasOwn(options, 'signal') || options.signal === undefined) return null;
1321	  const { signal } = options;
1322	  if (signal instanceof AbortSignal) return signal;
1323	  throw new TypeError('executeWorkflowAsync options.signal must be an AbortSignal');
1324	}
1325	
1326	export function executeWorkflow(workflow, input = {}) {
1327	  const nodes = validateWorkflow(workflow);
1328	  // Business operations are asynchronous: the synchronous entry must refuse
1329	  // a workflow that names any before a single node executes.
1330	  for (const node of nodes.values()) {
1331	    const binding = actionBindings.get(node);
1332	    if (binding && binding.name !== null) {
1333	      throw new Error(`action node ${node.id} names business operation "${binding.name}", which must run asynchronously; use executeWorkflowAsync instead of executeWorkflow`);
1334	    }
1335	  }
1336	
1337	  const state = createRunState(nodes, workflow, input);
1338	
1339	  for (;;) {
1340	    const step = advanceSchedule(state);
1341	
1342	    if (step.kind === 'blocked') {
1343	      return { status: 'blocked', context: state.context, trace: state.trace, blockedNodes: step.waiting };
1344	    }
1345	    if (step.kind === 'completed') {
1346	      return { status: 'completed', result: state.endResult, context: state.context, trace: state.trace };
1347	    }
1348	    if (step.kind === 'end') continue;
1349	
1350	    const early = applyRegularNode(step.node, state);
1351	    if (early) return early;
1352	  }
1353	}
1354	
1355	// Attaches compensation results to a failed run. Successful outputs and the
1356	// original terminal status stay untouched; compensation records live on
1357	// their own fields, never in the regular node trace.
1358	async function withCompensation(result, state, operations) {
1359	  const outcome = await compensateRun(state, operations);
1360	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
1361	  result.compensationAttempts = outcome.attempts;
1362	  return result;
1363	}
1364	
1365	// The cancelled terminal shape: the run stops where it is, keeps the
1366	// context, trace and attempt records produced so far, and never carries a
1367	// success result. Compensation for already-succeeded actions is attached by
1368	// withCompensation under the usual rules.
1369	function cancelledResult(state) {
1370	  return {
1371	    status: 'cancelled',
1372	    context: state.context,
1373	    trace: state.trace,
1374	    actionAttempts: state.actionAttempts,
1375	  };
1376	}
1377	
1378	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1379	  const signal = resolveRunSignal(options);
1380	  const nodes = validateWorkflow(workflow);
1381	  verifyOperations(nodes, operations);
1382	
1383	  const state = createRunState(nodes, workflow, input);
1384	
1385	  // A signal that is already aborted stops the run before the first node —
1386	  // but only after the definition and the operation registrations above have
1387	  // been checked. Nothing executes and nothing is compensated.
1388	  if (signal && signal.aborted) {
1389	    return withCompensation(cancelledResult(state), state, operations);
1390	  }
1391	
1392	  for (;;) {
1393	    // Once the signal fires, no new regular node runs and no new business
1394	    // action attempt starts; the run ends cancelled with whatever state it
1395	    // reached, even if an end node was already visited on another branch.
1396	    if (signal && signal.aborted) {
1397	      return withCompensation(cancelledResult(state), state, operations);
1398	    }
1399	
1400	    const step = advanceSchedule(state);
1401	
1402	    if (step.kind === 'blocked') {
1403	      // Unmet dependencies end the run; successful compensable actions are
1404	      // rolled back even though an end node may already have been reached.
1405	      return withCompensation({
1406	        status: 'blocked', context: state.context, trace: state.trace,
1407	        blockedNodes: step.waiting, actionAttempts: state.actionAttempts,
1408	      }, state, operations);
1409	    }
1410	    if (step.kind === 'completed') {
1411	      // A completed run never invokes compensation.
1412	      return {
1413	        status: 'completed', result: state.endResult, context: state.context,
1414	        trace: state.trace, actionAttempts: state.actionAttempts,
1415	        compensationStatus: 'not_needed', compensationAttempts: [],
1416	      };
1417	    }
1418	    if (step.kind === 'end') continue;
1419	
1420	    const ready = step.node;
1421	    if (ready.type === 'action') {
1422	      const binding = actionBindings.get(ready);
1423	      if (binding.name !== null) {
1424	        // Nodes execute one at a time in declaration order; awaiting here
1425	        // never lets another node jump ahead.
1426	        const actionResult = await runBusinessAction(
1427	          ready, binding, operations[binding.name], state.context, state.actionAttempts, signal);
1428	        if (!actionResult.ok) {
1429	          if (actionResult.cancelled) {
1430	            // Cancelled while the action was in flight or waiting to retry:
1431	            // the attempt records produced so far stay as they are.
1432	            return withCompensation(cancelledResult(state), state, operations);
1433	          }
1434	          // Retries are exhausted: stop immediately with prior input/output
1435	          // preserved, no output for this node and no successors activated —
1436	          // even if an end node was already reached — then compensate every
1437	          // earlier successful action that asked for it.
1438	          return withCompensation({
1439	            status: 'action_failed', nodeId: ready.id, attempts: binding.retry.attempts,
1440	            error: actionResult.error, context: state.context, trace: state.trace,
1441	            actionAttempts: state.actionAttempts,
1442	          }, state, operations);
1443	        }
1444	        // Capture the compensation snapshots from the state before the new
1445	        // output key lands: the action's own return value is handed to the
1446	        // compensation separately as its third argument.
1447	        const compensationSnapshot = binding.compensation === null ? null : {
1448	          input: structuredClone(state.context.input),
1449	          output: structuredClone(state.context.output),
1450	          result: structuredClone(actionResult.value),
1451	        };
1452	        setNodeOutput(state.context.output, ready.id, actionResult.value);
1453	        if (compensationSnapshot) {
1454	          // Each node completes at most once, so retried-then-successful
1455	          // actions and shared join nodes are scheduled for compensation
1456	          // exactly once.
1457	          state.compensable.push({ nodeId: ready.id, binding, snapshot: compensationSnapshot });
1458	        }
1459	        for (const target of successorTargets.get(ready)) state.activated.add(target);
1460	        state.completed.add(ready.id);
1461	        continue;
1462	      }
1463	    }
1464	
1465	    const early = applyRegularNode(ready, state);
1466	    if (early) {
1467	      early.actionAttempts = state.actionAttempts;
1468	      // A failed form (invalid_input) or failed condition evaluation
1469	      // (invalid_condition) ends normal execution and triggers compensation
1470	      // of the successful business actions that ran earlier.
1471	      return withCompensation(early, state, operations);
1472	    }
1473	  }
1474	}
