catch (e) { console.log("redefine index throws:", e.constructor.name); }
console.log("isBoxedPrimitive(new Number):", t.isBoxedPrimitive(new Number(1)));
console.log("globals:", typeof globalThis.DOMException, typeof globalThis.Blob, typeof globalThis.CryptoKey);
// boxed symbol clone behavior (leaf skip then clone reports)
try { structuredClone(Object(Symbol("x"))); console.log("boxed symbol: cloned"); }
catch (e) { console.log("boxed symbol: throws", e.name); }
